34: let game={active:false,seed:0,stage:0,biome:null,enemy:null,hp:100,maxHp:100,attack:12,armor:2,potions:2,relics:[],coins:0,level:1,abilityCd:0,paused:false,turn:0,log:'',fx:0,auto:true};
35: let timer=null,sceneTime=0,soundOn=false,audioCtx=null;
36: const rand=(min,max)=>Math.floor(Math.random()*(max-min+1))+min;
37: function seeded(seed){let n=seed>>>0;return()=>{n=(n*1664525+1013904223)>>>0;return n/4294967296}}
38: function setLog(t){game.log=t;$('battleLog').textContent=t}
39: function startGame(){clearInterval(timer);game={active:true,seed:rand(10000,99999),stage:0,biome:null,enemy:null,hp:100,maxHp:100,attack:12,armor:2,potions:2,relics:[],coins:0,level:1,abilityCd:0,paused:false,turn:0,log:'',fx:0,auto:true};$('runTag').textContent='EXPEDITION · '+game.seed;$('seedText').textContent='SEED · '+game.seed;showStage(0);setLog('The road stirs. Your blade answers.');updateUI();$('overlay').classList.add('hidden');timer=setInterval(tick,1050)}
40: function showStage(stage){game.stage=stage;let options=stage===0?first:stage===1?second:['castle'];let idx=rand(0,options.length-1), key=options[idx];game.biome=key;let data=biomes[key];let hp=data.hp+Math.max(0,stage-1)*8;game.enemy={name:data.enemy,hp,maxHp:hp,atk:data.atk+(stage===2?1:0),icon:data.enemyIcon};$('regionLabel').textContent=stage===2?'THE LAST REALM':stage===1?'THE SECOND REALM':'THE FIRST REALM';$('stageCount').textContent='✦ '+(stage+1)+' / 3';$('biomeIcon').textContent=data.icon;$('biomeName').textContent=data.name;$('biomeNote').textContent=data.weather;$('battleBanner').textContent=stage===2?'FINAL ENCOUNTER':'AUTO-BATTLE · '+(stage+1)+' OF 3';$('enemyName').innerHTML='☠ &nbsp;'+data.enemy.toUpperCase();$('enemyLevel').textContent=stage===2?'BOSS':'LV. '+(stage+1);$('enemyStatus').textContent=stage===2?'The last king waits':'Hostile';$('routeNote').textContent=stage===2?'The ruined castle is always the last stop. No one knows what comes after.':'The terrain changes with every run. No two paths are alike.';updateRoute();drawScene();setLog(stage===2?'Castle Mourning rises from the fog. The Hollow King sees you.':`${data.enemy} blocks the way through ${data.name}.`);updateUI()}
41: function updateRoute(){let html='';let labels=[game.stage>0?biomes[game.previous0||'cave'].name:'A wild beginning',game.stage>1?biomes[game.previous1||'desert'].name:'Beyond the wilds','Castle Mourning'];for(let i=0;i<3;i++){let key=i===game.stage?game.biome:i===2?'castle':i===0?game.previous0:game.previous1;let current=i===game.stage,done=i<game.stage;let icon=key?biomes[key].icon:['?','Ⅱ','♜'][i];let title=key?biomes[key].name:['A wild beginning','Beyond the wilds','The last keep'][i];let type=key?biomes[key].type:['CAVE · FOREST · SWAMP','DESERT · VOLCANO · BEACH','RUINED GOTHIC CASTLE'][i];html+=`<div class="route ${current?'current':''} ${done?'done':''}"><div class="route-icon">${icon}</div><div class="route-copy"><div class="route-name">${title}</div><div class="route-type">${type}</div></div><span class="route-state">${done?'CLEARED':current?'NOW':'—'}</span></div>`}$('routeList').innerHTML=html}
42: function tick(){if(!game.active||game.paused||!game.enemy||game.enemy.hp<=0)return;game.turn++;if(game.abilityCd>0)game.abilityCd--;let damage=game.attack+rand(-2,3);game.enemy.hp=Math.max(0,game.enemy.hp-damage);game.fx=1;setLog(`You strike ${game.enemy.name} for ${damage} damage.`);playTone(300,0.07);updateUI();if(game.enemy.hp<=0){setTimeout(victory,700);return}setTimeout(()=>{if(!game.active||game.paused||!game.enemy||game.enemy.hp<=0)return;let raw=game.enemy.atk+rand(-2,2),hit=Math.max(1,raw-game.armor);game.hp=Math.max(0,game.hp-hit);game.fx=-1;setLog(`${game.enemy.name} hits you for ${hit} damage${game.armor?` (${game.armor} absorbed)`:''}.`);playTone(110,0.09);updateUI();if(game.hp<=0)setTimeout(defeat,700)},430)}
43: function useAbility(){if(!game.active||game.paused||!game.enemy||game.enemy.hp<=0||game.abilityCd>0)return;let damage=Math.round(game.attack*1.8)+rand(2,5);game.enemy.hp=Math.max(0,game.enemy.hp-damage);game.abilityCd=3;game.fx=1;setLog(`Ember Slash tears through ${game.enemy.name} for ${damage} damage!`);playTone(480,0.11);updateUI();if(game.enemy.hp<=0)setTimeout(victory,650)}
44: function usePotion(){if(!game.active||!game.potions||game.hp>=game.maxHp)return;let healed=Math.min(32,game.maxHp-game.hp);game.hp+=healed;game.potions--;setLog(`You drink a field tonic and recover ${healed} vitality.`);playTone(620,0.13);updateUI()}
45: function toggleAuto(){game.paused=!game.paused;$('autoBtn').classList.toggle('active',!game.paused);$('autoBtn').setAttribute('aria-pressed',String(!game.paused));$('autoLabel').innerHTML=game.paused?'▶ &nbsp; RESUME':'Ⅱ &nbsp; AUTO';$('turnLabel').textContent=game.paused?'PAUSED':'AUTO-PLAYING';if(!game.paused&&game.active)setLog('The battle resumes.')}
46: function victory(){if(!game.active)return;game.active=false;game.coins+=12+game.stage*5;updateUI();if(game.stage===2){clearInterval(timer);showEnding(true);return}showReward()}
47: function showReward(){let pool=[...relics].sort(()=>Math.random()-.5).slice(0,3);let offers=pool.map((r,i)=>`<button class="choice-card" data-choice="${i}"><span class="choice-glyph">${r.glyph}</span><span class="choice-copy"><span class="choice-name">${r.name}</span><span class="choice-desc">${r.desc}</span></span><span class="choice-plus">${r.bonus}</span></button>`).join('');let heal=Math.min(20,game.maxHp-game.hp);$('modal').innerHTML=`<div class="modal-kicker">✦ &nbsp;REALM ${game.stage+1} CLEARED</div><h1>A small light<br>in the dark.</h1><p>${game.enemy.name} falls. You gather <b style="color:var(--gold)"> ${12+game.stage*5} shards</b> from the remains. Choose one relic for the road ahead${heal?` — and recover ${heal} vitality`:''}.</p><div class="choice-list">${offers}</div><div class="modal-buttons"><button class="secondary-btn" id="skipReward">Leave it behind</button></div>`;$('overlay').classList.remove('hidden');$('modal').querySelectorAll('[data-choice]').forEach(btn=>btn.onclick=()=>{let relic=pool[Number(btn.dataset.choice)];relic.apply(game);game.relics.push(relic);advance(heal,`You claim ${relic.name}. ${relic.bonus}.`)});$('skipReward').onclick=()=>advance(heal,'You leave the relics behind and press on.')}
48: function advance(heal,msg){$('overlay').classList.add('hidden');game.hp=Math.min(game.maxHp,game.hp+heal);if(game.stage===0)game.previous0=game.biome;if(game.stage===1)game.previous1=game.biome;game.stage++;game.active=true;showStage(game.stage);setLog(msg);updateUI()}
49: function defeat(){if(!game.active)return;game.active=false;clearInterval(timer);showEnding(false)}
50: function showEnding(won){$('modal').innerHTML=won?`<div class="modal-kicker">✦ &nbsp;THE END OF THE ROAD</div><h1>The last ember<br>still burns.</h1><p>The Hollow King is no more. Through cave, wilds, and ruin, you carried the light. The realm will remember Rook.</p><p style="color:var(--gold);font:10px var(--mono);letter-spacing:.1em">RUN ${game.seed} &nbsp;·&nbsp; ${game.relics.length} RELICS &nbsp;·&nbsp; ${game.coins} SHARDS</p><div class="modal-buttons"><button class="primary-btn" id="againBtn">Begin another journey →</button></div>`:`<div class="modal-kicker">✦ &nbsp;THE ROAD GOES QUIET</div><h1>Even embers<br>fade to ash.</h1><p>Rook's journey ends in ${game.biome?biomes[game.biome].name:'the wilds'}. Another wanderer may yet make it through.</p><p style="color:var(--gold);font:10px var(--mono);letter-spacing:.1em">RUN ${game.seed} &nbsp;·&nbsp; REALMS REACHED ${game.stage+1}</p><div class="modal-buttons"><button class="primary-btn" id="againBtn">Rise and try again →</button></div>`;$('overlay').classList.remove('hidden');$('againBtn').onclick=startGame;setLog(won?'The Hollow King is gone. The ash settles.':'Your light has gone out.')}
51: function updateUI(){let hpPct=game.maxHp?Math.max(0,game.hp/game.maxHp*100):0,ep=game.enemy?Math.max(0,game.enemy.hp/game.enemy.maxHp*100):0;$('playerHpText').textContent=`${game.hp} / ${game.maxHp}`;$('playerHpBar').style.width=hpPct+'%';$('enemyHpText').textContent=game.enemy?`${game.enemy.hp} / ${game.enemy.maxHp}`:'— / —';$('enemyHpBar').style.width=ep+'%';$('playerPower').textContent='ATK '+game.attack;$('playerLevel').textContent='LV. '+game.level;$('statAttack').textContent=game.attack;$('statArmor').textContent=game.armor;$('statRelics').textContent=game.relics.length+' / 3';$('coinCount').textContent='◈ '+game.coins;$('potionCount').textContent='× '+game.potions;$('packLabel').textContent=game.potions+' TONIC'+(game.potions===1?'':'S');$('playerStatus').textContent=game.hp<35?'Wounded':game.active?'Fighting':'Ready for the road';$('enemyPower').textContent=game.enemy?'ATK '+game.enemy.atk:'ATK —';$('abilityBtn').disabled=!game.active||game.paused||game.abilityCd>0||!game.enemy||game.enemy.hp<=0;$('abilitySub').textContent=game.abilityCd>0?`Recharges · ${game.abilityCd} turns`:'Powerful strike · ready';$('potionBtn').disabled=!game.active||!game.potions||game.hp>=game.maxHp;$('turnLabel').textContent=game.active?(game.paused?'PAUSED':'AUTO-PLAYING'):'PAUSED';let items=[{glyph:'⚔',title:'Old iron blade'},...game.relics.map(r=>({glyph:r.glyph,title:r.name})),...Array(Math.max(0,2-game.relics.length)).fill({glyph:'◈',title:'Traveler’s charm'})].slice(0,3);$('inventory').innerHTML=items.map((it,i)=>`<div class="inventory-item" title="${it.title}">${it.glyph}${i>0&&i<=game.relics.length?'<small>✦</small>':''}</div>`).join('')}
52: function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
53: function poly(points,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fill()}
54: function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
