-:root{--ink:#f3efe6;--muted:#a19d97;--faint:#696969;--gold:#e9b86a;--line:#343332;--panel:#1a1b1e;--deep:#111214;--red:#e27768;--green:#99be8f;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--display:'Unbounded',sans-serif}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:#101114;color:var(--ink);font-family:var(--sans);background-image:radial-gradient(ellipse at 50% -20%,#2b2a28 0%,transparent 55%)}button{font:inherit;color:inherit}button:focus-visible{outline:2px solid var(--gold);outline-offset:3px}.shell{max-width:1280px;margin:0 auto;padding:24px 36px 36px}.topbar{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding:0 0 17px}.brand{display:flex;align-items:center;gap:12px}.brand-mark{width:32px;height:32px;display:grid;place-items:center;border:1px solid #756044;color:var(--gold);font-size:17px;transform:rotate(45deg)}.brand-mark span{transform:rotate(-45deg)}.brand-name{font:600 12px var(--display);letter-spacing:.11em}.brand-sub{font:10px var(--mono);letter-spacing:.08em;color:var(--muted);margin-top:5px}.top-right{display:flex;align-items:center;gap:18px}.run-tag{font:10px var(--mono);letter-spacing:.12em;color:var(--muted);text-transform:uppercase}.sound-btn{background:transparent;border:1px solid var(--line);color:var(--muted);width:34px;height:34px;cursor:pointer}.layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:22px;padding-top:23px}.main{min-width:0}.section-eyebrow{font:10px var(--mono);letter-spacing:.18em;color:var(--gold);text-transform:uppercase}.scene-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.stage-label{display:flex;align-items:center;gap:9px}.stage-number,.seed{font:10px var(--mono);color:var(--faint)}.scene-wrap{position:relative;overflow:hidden;border:1px solid #44413b;background:#282722;min-height:310px;aspect-ratio:2.08/1}.scene-wrap canvas{display:block;width:100%;height:100%;image-rendering:pixelated}.scene-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(0deg,rgba(13,13,14,.62),transparent 30%,rgba(13,13,14,.07) 65%,rgba(13,13,14,.12))}.scene-caption{position:absolute;left:20px;bottom:15px;display:flex;align-items:end;gap:11px;text-shadow:0 2px 6px #000}.caption-icon{font-size:21px}.caption-name{font:500 17px Georgia,serif}.caption-note{font:9px var(--mono);text-transform:uppercase;letter-spacing:.12em;color:#d4cfc5;margin-top:3px}.battle-banner{position:absolute;right:17px;top:15px;background:#141517c9;padding:7px 10px;border:1px solid #ffffff24;font:9px var(--mono);text-transform:uppercase;letter-spacing:.1em;color:#e3cda9}.combatants{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:17px}.fighter{border:1px solid var(--line);background:#191a1c;padding:13px 15px 14px}.fighter.player{border-top:2px solid #b98c52}.fighter.enemy{border-top:2px solid #9a514b}.fighter-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:9px}.fighter-name{font:600 11px var(--mono);letter-spacing:.03em}.fighter-level{font:9px var(--mono);color:var(--faint)}.health-meta{display:flex;justify-content:space-between;font:9px var(--mono);color:var(--muted);margin-bottom:5px}.health-track{height:5px;background:#333337;overflow:hidden}.health-fill{height:100%;background:var(--green);transition:width .35s ease}.enemy .health-fill{background:var(--red)}.underbar{display:flex;justify-content:space-between;margin-top:9px;color:var(--faint);font:9px var(--mono)}.battle-log{min-height:35px;margin-top:12px;padding:9px 12px;border-left:2px solid #80613d;background:#1a1918;color:#c8c0b3;font:11px var(--mono);display:flex;align-items:center}.controls{display:flex;gap:9px;margin-top:13px;align-items:stretch}.action{border:1px solid #48433a;background:#29251f;padding:10px 15px;min-height:46px;cursor:pointer;transition:background .15s,border .15s;display:flex;align-items:center;gap:9px;flex:1;text-align:left}.action:hover:not(:disabled){background:#373025;border-color:#967144}.action:disabled{opacity:.42;cursor:not-allowed}.action-icon{font-size:17px;color:var(--gold)}.action-title{font:500 10px var(--mono);display:block}.action-sub{display:block;color:var(--faint);font:9px var(--mono);margin-top:3px}.action.quick{max-width:143px;flex:0 0 auto;background:#202927;border-color:#43594e}.action.quick .action-icon{color:#9bc6a0}.action.auto{max-width:112px;flex:0 0 auto;justify-content:center;text-align:center;background:#222326;border-color:#444}.action.auto.active{color:var(--green);border-color:#516a56}.action.auto .action-title{font-size:9px}.action-status{font:9px var(--mono);color:var(--faint);align-self:center;white-space:nowrap;margin-left:auto}.side{display:flex;flex-direction:column;gap:12px}.side-panel{border:1px solid var(--line);background:linear-gradient(155deg,#1d1e20,#18191b);padding:16px}.panel-title{font:10px var(--mono);text-transform:uppercase;letter-spacing:.13em;color:var(--muted);display:flex;justify-content:space-between;align-items:center}.hero-block{display:flex;gap:13px;align-items:center;margin:15px 0 12px}.hero-portrait{width:59px;height:64px;background:#31291e;border:1px solid #594735;display:grid;place-items:center;font-size:33px;position:relative}.hero-portrait:after{content:'';position:absolute;inset:4px;border:1px solid #94734a55}.hero-name{font:500 17px Georgia,serif}.hero-class{color:var(--muted);font:9px var(--mono);text-transform:uppercase;letter-spacing:.08em;margin-top:6px}.stat-line{display:flex;justify-content:space-between;padding:8px 0;border-top:1px solid #303033;font:10px var(--mono);color:var(--muted)}.stat-line b{color:var(--ink);font-weight:500}.stat-symbol{color:var(--gold);margin-right:7px}.inventory{display:flex;gap:7px;margin-top:13px}.inventory-item{width:42px;height:42px;border:1px solid #48453f;background:#242322;display:grid;place-items:center;font-size:19px;position:relative}.inventory-item small{position:absolute;right:3px;bottom:2px;color: